          "title": "Query",
          "type": "string"
        },
        "id": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Message ID for direct lookup (returns single message).",
          "title": "Id"
        },
        "label": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter by label (e.g., \"INBOX\", \"SENT\").",
          "title": "Label"
        },
        "max_results": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": 10,
          "description": "Maximum number of results to return.",
          "title": "Max Results"
        },
        "include_spam_trash": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "default": false,
          "description": "Include spam and trash in results.",
          "title": "Include Spam Trash"
        },
        "format": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "full",
          "description": "Email format to return (\"full\", \"metadata\", \"minimal\", \"raw\").",
          "title": "Format"
        }
      },
      "title": "gmail_find_email_args",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "query",
        "id",
        "label",
        "max_results",
        "include_spam_trash",
        "format"
      ]
    }
